import { test, expect } from '@playwright/test';

// Generated by Testwise. Do not hand-edit locators here --
// edit the plain-English steps and regenerate instead.
test('Login with invalid credentials shows an error', async ({ page }, testInfo) => {
  const consoleErrors: string[] = [];
  const networkErrors: string[] = [];
  page.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });
  page.on('requestfailed', (req) => { networkErrors.push(`${req.method()} ${req.url()} - ${req.failure()?.errorText}`); });
  page.on('response', (res) => { if (res.status() >= 500) networkErrors.push(`${res.status()} ${res.url()}`); });
  try {
  await test.step("Step 0: go to http://localhost:4799/login", async () => {
    await page.goto("http://localhost:4799/login");
  });

  await test.step("Step 1: fill username with \"wrong_user\"", async () => {
    const el1 = page.getByRole('textbox', { name: 'username' });
    await el1.first().fill("wrong_user");
  });

  await test.step("Step 2: fill password with \"wrong_pass\"", async () => {
    const el2 = page.getByRole('textbox', { name: 'password' });
    await el2.first().fill("wrong_pass");
  });

  await test.step("Step 3: click the Log in button", async () => {
    const el3 = page.getByRole('button', { name: 'Log' });
    await el3.first().click();
  });

  await test.step("Step 4: expect the login error to show \"Invalid username or password\"", async () => {
    const assert4 = page.getByText('Invalid username or password');
    await expect(assert4.first()).toContainText('Invalid username or password');
  });
  } finally {
    await testInfo.attach('console-errors.json', { body: Buffer.from(JSON.stringify(consoleErrors)), contentType: 'application/json' });
    await testInfo.attach('network-errors.json', { body: Buffer.from(JSON.stringify(networkErrors)), contentType: 'application/json' });
  }
});
